ActionsSubscriber:
/** Interface implemented by the client to receive action-log upserts. */
export interface ActionsSubscriber {
  entry(record: ActionLogEntry): Awaitable<void>;
  /**
   * @deprecated Fires after the subscription has caught up to the current time. However, this is
   * only a useful signal when a subscription is being used to enumerate past actions using a
   * distant-past `startAfter`. This is not the correct way to use `subscribeToActions()`; use
   * `listActions()` instead.
   */
  ready(): Awaitable<void>;
}

export type ActionDescription = {
  actionKind?: ActionKind;
  autoApprovable?: boolean;
  awaitDecision?: boolean;
  description: string;
  descriptionIsComplete?: boolean;
  fields?: ActionField[];
  implementsRevert: boolean;
  pushedCommits?: string[];
  title: string;
};

export type ActionField = {
  items: string[];
  kind: "list";
  label: string;
  truncated?: {
    shownBytes: number;
    totalBytes: number;
  };
} | {
  kind: "file";
  label: string;
  mediaType: string;
  name: string;
  origin: "agent" | "provider";
  sha256?: string;
  size: number;
  truncated?: {
    shownBytes: number;
    totalBytes: number;
  };
} | {
  kind: "inline";
  label: string;
  truncated?: {
    shownBytes: number;
    totalBytes: number;
  };
  value: string;
} | {
  kind: "json";
  label: string;
  truncated?: {
    shownBytes: number;
    totalBytes: number;
  };
  value: string;
} | {
  kind: "text";
  label: string;
  syntax?: ActionFieldSyntax;
  truncated?: {
    shownBytes: number;
    totalBytes: number;
  };
  value: string;
};

export type ActionFieldSyntax = "html" | "markdown" | "sql";

export type ActionKind = {
  label: string;
  tag: string;
};

export type ActionLogEntry = {
  appliedAt?: Date;
  autoApproved?: boolean;
  createdAt: Date;
  creation?: true;
  description: ActionDescription;
  gatekeeperId?: number;
  id: number;
  resolvedBy?: AiChatAuthorInfo;
  resourceTitle: string;
  resourceUrl?: string;
