} | {
  appliedAt?: Date;
  createdAt: Date;
  description: HookDescription;
  enabled: boolean;
  gatekeeperId?: number;
  hookId?: number;
  id: number;
  resourceTitle: string;
  resourceUrl?: string;
  state: ActionState;
  type: "bindHook";
} | {
  appliedAt?: Date;
  createdAt: Date;
  description: ObservationDescription;
  gatekeeperId?: number;
  id: number;
  resourceTitle: string;
  resourceUrl?: string;
  state: ActionState;
  type: "observation";
};

export type ActionState = "approved" | "pending" | "rejected";

export type AiChatAuthorInfo = {
  commitEmail?: string;
  id: string;
  name: string;
  type: "agent" | "gadget" | "user";
};

export type HookDescription = {
  description: string;
